use ratatui::{prelude::*, widgets::*}; use crate::{app::App, widgets::status_bar}; pub fn draw(f:&mut Frame, app:&mut App, area:Rect){ let chunks=Layout::vertical([Constraint::Min(5),Constraint::Length(1)]).split(area); let items:Vec<ListItem>=app.logs.iter().rev().take(200).map(|l|ListItem::new(l.clone())).collect(); f.render_widget(List::new(items).block(Block::bordered().border_style(app.theme.border()).title(" SSHDeck Events ")), chunks[0]); status_bar::draw(f, app, chunks[1], "l logs · Esc back"); }